// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";

/**
 * @title VestingEscrow
 * @dev A simple vesting contract to lock tokens for a beneficiary with a TGE and linear vesting.
 * An instance of this contract is created for each crowdsale participant when they claim their tokens.
 * Vesting schedule: 25% immediate release at TGE (claim time), with the remaining 75%
 * vesting linearly over 9 months.
 */
contract VestingEscrow {
    /// @notice The ERC20 token being vested.
    IERC20 public immutable token;
    /// @notice The beneficiary of the vested tokens.
    address public immutable beneficiary;
    /// @notice The total amount of tokens vested in this contract.
    uint256 public immutable totalAmount;
    /// @notice The timestamp when the vesting period begins.
    uint64 public immutable startTime;

    /// @notice The amount of tokens that have already been released to the beneficiary.
    uint256 public releasedAmount;

    /// @notice The percentage of tokens released at the Token Generation Event (TGE).
    uint256 public constant TGE_PERCENTAGE = 25; // 25%
    /// @notice The total duration of the linear vesting period.
    uint256 public constant VESTING_DURATION = 9 * 30 days;

    /// @notice Emitted when tokens are released to the beneficiary.
    event Released(uint256 amount);

    /**
     * @dev Sets up the vesting schedule.
     * @param _beneficiary The address that will receive the vested tokens.
     * @param _totalAmount The total amount of tokens to be vested.
     * @param _startTime The timestamp marking the beginning of the vesting period (TGE).
     * @param _token The ERC20 token contract address.
     */
    constructor(address _beneficiary, uint256 _totalAmount, uint64 _startTime, IERC20 _token) {
        require(_beneficiary != address(0), "VestingEscrow: beneficiary is zero address");
        require(_totalAmount > 0, "VestingEscrow: total amount is zero");
        require(address(_token) != address(0), "VestingEscrow: token is zero address");

        beneficiary = _beneficiary;
        totalAmount = _totalAmount;
        startTime = _startTime;
        token = _token;
    }

    /**
     * @dev Calculates the amount of tokens that can be released at the current time.
     */
    function releasable() public view returns (uint256) {
        return _vestedAmount(block.timestamp) - releasedAmount;
    }

    /**
     * @dev Releases the vested tokens to the beneficiary.
     * Can only be called by the beneficiary.
     */
    function release() public {
        require(msg.sender == beneficiary, "VestingEscrow: caller is not the beneficiary");

        uint256 unreleased = releasable();
        require(unreleased > 0, "VestingEscrow: no tokens are due");

        releasedAmount += unreleased;

        bool sent = token.transfer(beneficiary, unreleased);
        require(sent, "VestingEscrow: token transfer failed");

        emit Released(unreleased);
    }

    /**
     * @dev Internal function to calculate the total amount of vested tokens at a given timestamp.
     * @param _timestamp The timestamp to check.
     * @return The total vested amount.
     */
    function _vestedAmount(uint256 _timestamp) internal view returns (uint256) {
        if (_timestamp < startTime) {
            return 0;
        }

        uint256 tgeAmount = (totalAmount * TGE_PERCENTAGE) / 100;

        if (_timestamp >= startTime + VESTING_DURATION) {
            return totalAmount;
        }

        uint256 vestingPeriodAmount = totalAmount - tgeAmount;
        uint256 vestedOverTime = (vestingPeriodAmount * (_timestamp - startTime)) / VESTING_DURATION;

        return tgeAmount + vestedOverTime;
    }
}


/**
 * @title MerkleCrowdsale
 * @dev A crowdsale contract that uses a Merkle tree for whitelisting.
 * It includes soft/hard caps, per-user contribution limits, and a vesting mechanism.
 * Funds are accepted in ETH. If the soft cap is met, funds go to a project wallet.
 * Otherwise, contributors can claim a refund. Tokens are distributed via individual
 * VestingEscrow contracts.
 */
contract MerkleCrowdsale is Ownable, Pausable, ReentrancyGuard {
    /// @notice The ERC20 token being sold.
    IERC20 public immutable token;
    /// @notice How many token units a buyer gets per 1 ETH (10^18 wei).
    uint256 public immutable rate;
    /// @notice The timestamp when the sale starts.
    uint256 public immutable startTime;
    /// @notice The timestamp when the sale ends.
    uint256 public immutable endTime;
    /// @notice The minimum amount of ETH to be raised for the sale to succeed.
    uint256 public immutable softCap;
    /// @notice The maximum amount of ETH that can be raised.
    uint256 public immutable hardCap;
    /// @notice The address where funds are collected if the soft cap is reached.
    address payable public immutable wallet;
    /// @notice The Merkle root of the whitelist. Leaves are keccak256(abi.encodePacked(address, maxContribution)).
    bytes32 public immutable merkleRoot;

    /// @notice The total amount of ETH raised so far.
    uint256 public totalRaised;
    /// @notice Mapping from contributor address to their ETH contribution amount.
    mapping(address => uint256) public contributions;
    /// @notice Mapping from contributor address to the address of their vesting contract.
    mapping(address => address) public vestingContracts;
    /// @notice Mapping to track if a user has already claimed their tokens.
    mapping(address => bool) private _hasClaimedTokens;
    /// @notice Mapping to track if a user has already claimed their refund.
    mapping(address => bool) private _hasClaimedRefund;

    /// @notice The current status of the crowdsale.
    enum Status { PENDING, SUCCESS, FAILED }
    Status public saleStatus;

    /// @notice Emitted when a user successfully purchases tokens.
    event Purchased(address indexed user, uint256 ethAmount, uint256 tokenAmount);
    /// @notice Emitted when the crowdsale is finalized (either succeeds or fails).
    event Finalized(Status status);
    /// @notice Emitted when a user claims their tokens and a vesting contract is created.
    event TokensClaimed(address indexed user, address vestingContract, uint256 tokenAmount);
    /// @notice Emitted when a user claims their refund after a failed sale.
    event RefundClaimed(address indexed user, uint256 ethAmount);

    /**
     * @dev Contract constructor.
     * @param _rate Number of tokens per 1 ETH.
     * @param _startTime Sale start timestamp.
     * @param _endTime Sale end timestamp.
     * @param _softCap Minimum funding goal in wei.
     * @param _hardCap Maximum funding goal in wei.
     * @param _wallet Address to receive funds.
     * @param _merkleRoot Root of the whitelist Merkle tree.
     * @param _token The ERC20 token being sold.
     */
    constructor(
        uint256 _rate,
        uint256 _startTime,
        uint256 _endTime,
        uint256 _softCap,
        uint256 _hardCap,
        address payable _wallet,
        bytes32 _merkleRoot,
        IERC20 _token
    ) {
        require(_rate > 0, "Crowdsale: rate must be > 0");
        require(_startTime >= block.timestamp, "Crowdsale: start time must be in the future");
        require(_endTime > _startTime, "Crowdsale: end time must be after start time");
        require(_softCap > 0, "Crowdsale: soft cap must be > 0");
        require(_hardCap >= _softCap, "Crowdsale: hard cap must be >= soft cap");
        require(_wallet != address(0), "Crowdsale: wallet is the zero address");
        require(_merkleRoot != bytes32(0), "Crowdsale: merkle root is empty");
        require(address(_token) != address(0), "Crowdsale: token is the zero address");

        rate = _rate;
        startTime = _startTime;
        endTime = _endTime;
        softCap = _softCap;
        hardCap = _hardCap;
        wallet = _wallet;
        merkleRoot = _merkleRoot;
        token = _token;
        saleStatus = Status.PENDING;
    }

    /**
     * @dev Allows a whitelisted user to purchase tokens by sending ETH.
     * @param _maxContribution The maximum ETH amount this user is allowed to contribute (from the Merkle tree data).
     * @param _merkleProof The Merkle proof to verify the user's inclusion in the whitelist.
     */
    function purchase(uint256 _maxContribution, bytes32[] calldata _merkleProof)
        external
        payable
        whenNotPaused
        nonReentrant
    {
        require(block.timestamp >= startTime && block.timestamp <= endTime, "Crowdsale: not active");
        require(msg.value > 0, "Crowdsale: ETH amount must be > 0");
        require(totalRaised + msg.value <= hardCap, "Crowdsale: hard cap exceeded");

        bytes32 leaf = keccak256(abi.encodePacked(msg.sender, _maxContribution));
        require(MerkleProof.verify(_merkleProof, merkleRoot, leaf), "Crowdsale: invalid Merkle proof");

        uint256 newContribution = contributions[msg.sender] + msg.value;
        require(newContribution <= _maxContribution, "Crowdsale: user cap exceeded");

        contributions[msg.sender] = newContribution;
        totalRaised += msg.value;

        uint256 tokenAmount = msg.value * rate;
        emit Purchased(msg.sender, msg.value, tokenAmount);
    }

    /**
     * @dev Finalizes the crowdsale. Can only be called by the owner after the sale ends.
     * If the soft cap is met, funds are transferred to the wallet. Otherwise, the sale is marked
     * as failed, enabling refunds.
     */
    function finalize() external onlyOwner {
        require(saleStatus == Status.PENDING, "Crowdsale: already finalized");
        require(block.timestamp > endTime, "Crowdsale: not ended yet");

        if (totalRaised >= softCap) {
            saleStatus = Status.SUCCESS;
            (bool success, ) = wallet.call{value: totalRaised}("");
            require(success, "Crowdsale: failed to send funds to wallet");
        } else {
            saleStatus = Status.FAILED;
        }

        emit Finalized(saleStatus);
    }

    /**
     * @dev Allows a contributor to claim their purchased tokens after a successful sale.
     * This will deploy a new VestingEscrow contract for the user and transfer the tokens to it.
     */
    function claimTokens() external nonReentrant {
        require(saleStatus == Status.SUCCESS, "Crowdsale: sale was not successful");
        uint256 contribution = contributions[msg.sender];
        require(contribution > 0, "Crowdsale: you have no contribution");
        require(!_hasClaimedTokens[msg.sender], "Crowdsale: tokens already claimed");

        _hasClaimedTokens[msg.sender] = true;
        uint256 tokenAmount = contribution * rate;

        // This contract must hold enough tokens to distribute.
        require(token.balanceOf(address(this)) >= tokenAmount, "Crowdsale: insufficient token balance in contract");

        VestingEscrow escrow = new VestingEscrow(msg.sender, tokenAmount, uint64(block.timestamp), token);
        vestingContracts[msg.sender] = address(escrow);

        require(token.transfer(address(escrow), tokenAmount), "Crowdsale: token transfer to vesting contract failed");

        emit TokensClaimed(msg.sender, address(escrow), tokenAmount);
    }

    /**
     * @dev Allows a contributor to claim a refund if the sale failed to meet the soft cap.
     */
    function claimRefund() external nonReentrant {
        require(saleStatus == Status.FAILED, "Crowdsale: sale was not a failure");
        uint256 contribution = contributions[msg.sender];
        require(contribution > 0, "Crowdsale: you have no contribution");
        require(!_hasClaimedRefund[msg.sender], "Crowdsale: refund already claimed");

        _hasClaimedRefund[msg.sender] = true;

        (bool success, ) = msg.sender.call{value: contribution}("");
        require(success, "Crowdsale: refund transfer failed");

        emit RefundClaimed(msg.sender, contribution);
    }

    /**
     * @dev Pauses the sale. Can only be called by the owner.
     * Prevents new purchases.
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpauses the sale. Can only be called by the owner.
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev Fallback function to prevent accidental ETH transfers.
     */
    receive() external payable {
        revert("MerkleCrowdsale: direct ETH transfers not allowed");
    }

    // --- View Functions ---

    /**
     * @dev Returns the ETH contribution amount for a given user.
     */
    function getContribution(address _user) external view returns (uint256) {
        return contributions[_user];
    }

    /**
     * @dev Returns true if the user has claimed their tokens.
     */
    function hasClaimedTokens(address _user) external view returns(bool) {
        return _hasClaimedTokens[_user];
    }

    /**
     * @dev Returns true if the user has claimed their refund.
     */
    function hasClaimedRefund(address _user) external view returns(bool) {
        return _hasClaimedRefund[_user];
    }

    /**
     * @dev Checks if the crowdsale is currently active.
     */
    function isActive() public view returns (bool) {
        return block.timestamp >= startTime && block.timestamp <= endTime;
    }

    /**
     * @dev Checks if the crowdsale has ended.
     */
    function hasEnded() public view returns (bool) {
        return block.timestamp > endTime;
    }
}

